import java.util.*;
class Test {public static void main(String[] args){Solution s=new Solution();String[][] c={{"aa","a","false"},{"aa","a*","true"},{"ab",".*","true"},{"aab","c*a*b","true"},{"mississippi","mis*is*p*.","false"},{"ab",".*c","false"},{"a","ab*","true"}};for(String[] x:c)if(s.isMatch(x[0],x[1])!=Boolean.parseBoolean(x[2]))throw new AssertionError();String[] tokens={"a","b",".","a*","b*",".*"};for(String a:new String[]{"a","b","aa","ab","ba","bbb","aab"})for(String x:tokens)for(String y:tokens)for(String z:tokens){String p=x+y+z;if(s.isMatch(a,p)!=a.matches(p))throw new AssertionError(a+" "+p);}System.out.println("Samples and original edge/reference checks passed");}}